package mz.bam.seeky.android;
import android.app.*;import java.io.*;import java.nio.file.*;import java.util.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(manifest=Config.NONE,sdk=33,application=Application.class) @LooperMode(LooperMode.Mode.PAUSED)
public class BookRemovalTest {
 Application app;StudyStore store;File file;
 @Before public void setup()throws Exception{app=RuntimeEnvironment.getApplication();store=new StudyStore(app);file=new File(StudyFileProvider.directory(app),UUID.randomUUID()+".txt");Files.write(file.toPath(),"Livro completo".getBytes("UTF-8"));}
 @After public void close(){store.close();}
 long material(long subject,File source)throws Exception{return store.save("materials",0,StudyStore.values("subject",subject,"title","Livro","name","Livro.txt","mime","text/plain","hash",StudyFiles.hash(source),"path",source.getPath(),"bytes",source.length(),"created",1,"updated",1));}
 @Test public void deletingOneShelfBookRemovesSharedReferencesButKeepsStudyNotesAndReaderHistory()throws Exception{long first=material(0,file);long subject=store.save("subjects",0,StudyStore.values("title","Módulo","color",0,"created",1)),second=material(subject,file);long note=store.save("notes",0,StudyStore.values("subject",subject,"material",second,"title","Nota","body","Conservar","created",1,"updated",1));String uri=StudyFileProvider.uri(app,second).toString();try(ReaderStore reader=new ReaderStore(app)){reader.bookmark(uri,0,3,"Guardar");}LastReading.remember(app,StudyFileProvider.uri(app,second),"Livro.txt","text/plain","Livro","Livros",second);BookRemoval.Result result=BookRemoval.remove(app,store,first,file.getPath(),StudyFiles.hash(file));assertEquals(2,result.records);assertFalse(LastReading.get(app).exists());assertTrue(result.fileRemoved);assertFalse(file.exists());assertEquals(0,store.count("materials",null,null));assertEquals("Conservar",store.get("notes",note).s("body"));assertEquals(0,store.get("notes",note).n("material"));assertEquals(subject,store.get("notes",note).n("subject"));try(ReaderStore reader=new ReaderStore(app);android.database.Cursor cursor=reader.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM bookmark WHERE uri=?",new String[]{uri})){cursor.moveToFirst();assertEquals(1,cursor.getInt(0));}store.close();store=new StudyStore(app);Files.write(file.toPath(),"Outro livro".getBytes("UTF-8"));long fresh=material(0,file);assertTrue(fresh>second);assertNotEquals(uri,StudyFileProvider.uri(app,fresh).toString());}
 @Test public void externalOriginalIsNeverDeleted()throws Exception{File external=new File(app.getCacheDir(),"original.txt");Files.write(external.toPath(),"Original".getBytes("UTF-8"));long id=material(0,external);BookRemoval.Result r=BookRemoval.remove(app,store,id,external.getPath(),StudyFiles.hash(external));assertEquals(1,r.records);assertFalse(r.fileRemoved);assertTrue(external.exists());}
 @Test public void staleMenuCannotDeleteAChangedBook()throws Exception{long id=material(0,file);String hash=StudyFiles.hash(file);store.save("materials",id,StudyStore.values("path",file.getPath()+".changed"));try{BookRemoval.remove(app,store,id,file.getPath(),hash);fail();}catch(IOException expected){}assertNotNull(store.get("materials",id));assertTrue(file.exists());}
 @Test public void aFileWithOtherRemainingReferencesIsConserved()throws Exception{long id=material(0,file),group=store.save("subjects",0,StudyStore.values("title","Outro","color",0,"created",1)),other=material(group,file);store.save("materials",other,StudyStore.values("hash","another-identity"));BookRemoval.Result r=BookRemoval.remove(app,store,id,file.getPath(),StudyFiles.hash(file));assertEquals(1,r.records);assertFalse(r.fileRemoved);assertTrue(file.exists());assertNotNull(store.get("materials",other));}
}
